-- ---------------------------------------------
-- 00_schema.sql
-- ---------------------------------------------
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name = N'mold')
    EXEC(N'CREATE SCHEMA [mold]');
GO
IF 'mold' = 'mold' AND NOT EXISTS (SELECT 1 FROM sys.tables WHERE name = 'config' AND schema_id = schema_id('mold'))
    CREATE TABLE mold.config([key] VARCHAR(100) PRIMARY KEY, [value] NVARCHAR(1000));
GO

