-- ---------------------------------------------
-- 01_config.sql
-- ---------------------------------------------
create or alter proc mold.set_config(@key varchar(50), @value nvarchar(1000))
as
begin
    set nocount on;

    set @key = trim(isnull(@key, ''))

    if @key = ''
        raiserror('mold set config: key is required', 16, 1)

    if not exists (select 1 from mold.config where [key] = @key)
        insert into mold.config([key], [value])
        values (@key, @value)
    else
        update mold.config set [value] = @value where [key] = @key
end
go

create or alter function mold.get_config(@key varchar(50))
returns nvarchar(1000)
as
begin
    return (select [value] from mold.config where [key] = @key)
end
go


-- ---------------------------------------------
-- 02_debug.sql
-- ---------------------------------------------
create or alter proc mold.set_debugging(@category varchar(50), @value bit)
as
begin
    set nocount on;

    if @category = '*'
        set @category = 'all'

    set @category = 'debug.' + @category
    set @value = isnull(cast(@value as varchar(1)), '0')

    exec mold.set_config @category, @value
end
go

/*
    debugging levels:
        query  , q :  dynamic queries
        nquery , qn:  nested queries
        dquery , qd:  deep queries
        lquery , ql:  loop queries
        vars   , v :  local variables
        dvars  , vd:  deep variables
        lvars  , vl:  loop variables
        debug  , d :  debug
        log    , l :  log
        warning, w :  warnings
        trace  , t :  trace
        errors , e :  show error_message()
        result , r :  results
        config , c :  configs
        setting, s :  settings
        procedure,p:  procedures
        all   , * :  everything
*/
create or alter function mold.get_debugging(@category varchar(50))
returns bit
as
begin
    declare @result bit

    if @category = '*'
        set @category = 'all'

    set @category = 'debug.' + @category

    set @result = case when mold.get_config(@category) = '1' then 1 else 0 end

    return @result
end
go

create or alter function mold.is_debugging(@category varchar(500)) returns bit
as
begin
    return (case when exists
    (
        select 1 from string_split(@category, ',')
        where mold.get_debugging([value]) = 1
    ) or mold.get_debugging('all') = 1 then 1 else 0 end)
end
go


-- ---------------------------------------------
-- helpers/functions/base64_to_varbinary.sql
-- ---------------------------------------------
-- =============================================
-- mold.base64_to_varbinary
-- =============================================
-- Decodes a base64 string to varbinary.
--
-- Examples:
--   base64_to_varbinary(N'aGVsbG8=') -> 0x68656C6C6F
--   base64_to_varbinary(N'')         -> 0x
--   base64_to_varbinary(NULL)        -> NULL
-- =============================================
CREATE OR ALTER FUNCTION [mold].[base64_to_varbinary]
(
	 @s		VARCHAR(MAX)
) 
RETURNS VARBINARY(MAX)
AS
BEGIN
	if @s is null return null;

    -- SQL Server 2022+: return cast(N'' as xml).value('xs:base64Binary(sql:variable("@s"))', 'varbinary(max)');
    return cast(N'' as xml).value('xs:base64Binary(sql:variable("@s"))', 'varbinary(max)');
END

GO

go

-- ---------------------------------------------
-- helpers/functions/hex_to_varbinary.sql
-- ---------------------------------------------
-- =============================================
-- mold.hex_to_varbinary
-- =============================================
-- Decodes a hexadecimal string to varbinary.
--
-- The input is the hex digits without the 0x prefix (the format produced
-- by varbinary_to_hex). Case-insensitive: 'AB' and 'ab' decode to the
-- same byte. An odd number of hex digits is rejected by xs:hexBinary.
--
-- Examples:
--   hex_to_varbinary(N'AB')      -> 0xAB
--   hex_to_varbinary(N'ABCD')    -> 0xABCD
--   hex_to_varbinary(N'abcd')    -> 0xABCD
--   hex_to_varbinary(N'')        -> 0x
--   hex_to_varbinary(NULL)       -> NULL
--   hex_to_varbinary(N'ABC')     -> error: xs:hexBinary requires an even number of digits
-- =============================================
create or alter function mold.hex_to_varbinary
(
    @s nvarchar(max)
)
returns varbinary(max)
as
begin
    if @s is null return null;

    return cast(N'' as xml).value(
        'xs:hexBinary(sql:variable("@s"))',
        'varbinary(max)'
    );
end
go


-- ---------------------------------------------
-- helpers/functions/is_decimal.sql
-- ---------------------------------------------
create or alter function mold.is_decimal
(
	@x varchar(50)
)
returns bit
as
begin
	declare @result bit

	set @result = mold.is_empty(@x)

	if @result = 0
	begin
		declare @i int

		set @i = charindex('.', @x)

		if @i > 0
		begin
			declare @left varchar(50)
			declare @right varchar(50)

			set @left = case when @i > 1 then ltrim(left(@x, @i - 1)) else '' end
			set @right = ltrim(right(@x, len(@x) - @i))

			if @left = '' and @right = ''
				set @result = 0
			else
			if @left = ''
				set @result = mold.is_integer(@right)
			else
			if @right = ''
				set @result = mold.is_integer(@left)
			else
				set @result = mold.is_integer(@left) & mold.is_integer(@right)
		end
		else
			set @result = mold.is_integer(@x)
	end
	else
		set @result = 0

	return @result
end
go


