-- ---------------------------------------------
-- helpers/functions/shift_left.sql
-- ---------------------------------------------
create or alter function mold.shift_left(@a bigint, @n tinyint)
returns bigint
as
begin
	return
	(
		case
			when isnull(@n, 0) <= 0 then @a
			when isnull(@n, 0) = 63 then -9223372036854775808
			when isnull(@n, 0) > 63 then cast(0 as bigint)
			else
				@a * power(cast(2 as bigint), @n)
		end
	)
end

GO

go

-- ---------------------------------------------
-- helpers/functions/shift_right.sql
-- ---------------------------------------------
create or alter function mold.shift_right(@a bigint, @n tinyint)
returns bigint
as
begin
	return
	(
		case
			when isnull(@n, 0) <= 0 then @a
			else
				@a / power(2, @n)
		end
	)
end

GO

