-- ---------------------------------------------
-- helpers/functions/string_equals.sql
-- ---------------------------------------------
-- =============================================
-- mold.string_equals
-- =============================================
-- Returns 1 if @a and @b are equal under the requested options.
--
-- @trim       1 = trim both values before comparing
-- @ignoreCase 1 = case-insensitive comparison
--             0 = case-sensitive comparison
--
-- Null is treated as the empty string, so string_equals(NULL, '') = 1.
-- That matches the two-value semantics of a string comparison; if a
-- caller needs null to be distinct from '', check @a IS NULL and @b IS
-- NULL before calling.
--
-- Examples:
--   string_equals(N' a ', N'a',   1, 1) -> 1   -- trim + CI
--   string_equals(N'a',   N'A',   0, 1) -> 1
--   string_equals(N'a',   N'A',   0, 0) -> 0
-- =============================================
create or alter function mold.string_equals
(
    @a          nvarchar(max),
    @b          nvarchar(max),
    @trim       bit,
    @ignoreCase bit
)
returns bit
as
begin
    set @a = isnull(@a, N'');
    set @b = isnull(@b, N'');

    if @trim = 1
    begin
        set @a = trim(@a);
        set @b = trim(@b);
    end

    if @ignoreCase = 1
        return case
            when @a collate Latin1_General_CI_AS
               = @b collate Latin1_General_CI_AS then 1
            else 0
        end;

    return case
        when @a collate Latin1_General_CS_AS
           = @b collate Latin1_General_CS_AS then 1
        else 0
    end;
end
go


-- ---------------------------------------------
-- helpers/functions/trim_both.sql
-- ---------------------------------------------
-- =============================================
-- mold.trim_both
-- =============================================
-- Removes every leading and trailing character in @chars from @s.
-- Equivalent to TRIM(@chars FROM @s) on SQL Server 2022, and to
-- mold.trim_left(mold.trim_right(@s, @chars), @chars)
-- on older versions.
-- =============================================
create or alter function mold.trim_both
(
    @s     nvarchar(max),
    @chars nvarchar(100)
)
returns nvarchar(max)
as
begin
    return mold.trim_left(mold.trim_right(@s, @chars), @chars);
end

go

-- ---------------------------------------------
-- helpers/functions/trim_left.sql
-- ---------------------------------------------
-- =============================================
-- mold.trim_left
-- =============================================
-- Removes every leading character in @chars from @s.
-- Portable replacement for the SQL Server 2022 LEADING form of TRIM.
--
-- Examples:
--   trim_left(N'000124',   N'0')  -> N'124'
--   trim_left(N'   hello', N' ')  -> N'hello'
--   trim_left(N'xxabc',    N'x')  -> N'abc'
--   trim_left(NULL,        N'0')  -> NULL
-- =============================================
create or alter function mold.trim_left
(
    @s     nvarchar(max),
    @chars nvarchar(100)
)
returns nvarchar(max)
as
begin
    if @s is null or @chars is null or @chars = N''
        return @s;

    declare @i int = 1;
    declare @n int = len(@s);

    while @i <= @n and charindex(substring(@s, @i, 1), @chars) > 0
        set @i += 1;

    return substring(@s, @i, @n - @i + 1);
end

go

-- ---------------------------------------------
-- helpers/functions/trim_right.sql
-- ---------------------------------------------
-- =============================================
-- mold.trim_right
-- =============================================
-- Removes every trailing character in @chars from @s.
-- Portable replacement for the SQL Server 2022 TRAILING form of TRIM.
--
-- Examples:
--   trim_right(N'124.23000', N'0')  -> N'124.23'
--   trim_right(N'hello   ',  N' ')  -> N'hello'
--   trim_right(N'abcxx',     N'x')  -> N'abc'
--   trim_right(NULL,         N'0')  -> NULL
-- =============================================
create or alter function mold.trim_right
(
    @s     nvarchar(max),
    @chars nvarchar(100)
)
returns nvarchar(max)
as
begin
    if @s is null or @chars is null or @chars = N''
        return @s;

    declare @i int = len(@s);

    while @i > 0 and charindex(substring(@s, @i, 1), @chars) > 0
        set @i -= 1;

    return left(@s, @i);
end

go

-- ---------------------------------------------
-- helpers/functions/trim_trailing_zeros.sql
-- ---------------------------------------------
create or alter function mold.trim_trailing_zeros(@s nvarchar(max))
returns nvarchar(max)
as
begin
    while len(@s) > 0 and right(@s, 1) = '0'
        set @s = left(@s, len(@s) - 1);
    if right(@s, 1) = '.'
        set @s = left(@s, len(@s) - 1);
    return @s;
end
go


-- ---------------------------------------------
-- helpers/functions/varbinary_to_base64.sql
-- ---------------------------------------------
-- =============================================
-- mold.varbinary_to_base64
-- =============================================
-- Encodes varbinary to a base64 string.
--
-- Examples:
--   varbinary_to_base64(0x68656C6C6F) -> N'aGVsbG8='
--   varbinary_to_base64(0x)           -> N''
--   varbinary_to_base64(NULL)         -> NULL
-- =============================================
CREATE OR ALTER FUNCTION [mold].[varbinary_to_base64]
(
	 @Value		VARBINARY(MAX)
) 
RETURNS VARCHAR(MAX)
AS
BEGIN
	if @value is null return null;

    return cast(N'' as xml).value('xs:base64Binary(sql:variable("@value"))', 'nvarchar(max)');
END
GO

go

-- ---------------------------------------------
-- helpers/functions/varbinary_to_hex.sql
-- ---------------------------------------------
-- =============================================
-- mold.varbinary_to_hex
-- =============================================
-- Encodes varbinary to an uppercase hexadecimal string.
--
-- The output is the hex digits without the 0x prefix (the format accepted
-- by hex_to_varbinary). xs:hexBinary emits uppercase; wrap with
-- lower(varbinary_to_hex(@v)) if you need lowercase.
--
-- Examples:
--   varbinary_to_hex(0xAB)     -> N'AB'
--   varbinary_to_hex(0xABCD)   -> N'ABCD'
--   varbinary_to_hex(0x)       -> N''
--   varbinary_to_hex(NULL)     -> NULL
-- =============================================
create or alter function mold.varbinary_to_hex
(
    @v varbinary(max)
)
returns nvarchar(max)
as
begin
    if @v is null return null;

    return cast(N'' as xml).value(
        'xs:hexBinary(sql:variable("@v"))',
        'nvarchar(max)'
    );
end
go


-- ---------------------------------------------
-- functions/_rtrim_chars.sql
-- ---------------------------------------------
-- =============================================
-- mold._rtrim_chars
-- =============================================
-- Removes any trailing characters in @chars from @s. Portable replacement for
-- RTRIM(@s, @chars), which requires SQL Server 2022 / compat level 160+.
--
-- Examples:
--   _rtrim_chars(N'Users.',   N'.')   -> N'Users'
--   _rtrim_chars(N'Users..',  N'.')   -> N'Users'
--   _rtrim_chars(N'Users.  ', N'. ')  -> N'Users'
--   _rtrim_chars(NULL,        N'.')   -> NULL
-- =============================================
CREATE OR ALTER FUNCTION mold._rtrim_chars
(
    @s     nvarchar(max),
    @chars nvarchar(100)
)
RETURNS nvarchar(max)
AS
BEGIN
    IF @s IS NULL OR @chars IS NULL OR @chars = N''
        RETURN @s;

    DECLARE @i int = LEN(@s);
    WHILE @i > 0 AND CHARINDEX(SUBSTRING(@s, @i, 1), @chars) > 0
        SET @i -= 1;

    RETURN LEFT(@s, @i);
END
GO

go

-- ---------------------------------------------
-- functions/parse_table_name.sql
-- ---------------------------------------------
create or alter function mold.parse_table_name(@name nvarchar(1000))
returns @result table 
(
	[db] nvarchar(500),
	[schema] nvarchar(500),
	[table] nvarchar(500),
	[column] nvarchar(500)
)
as
begin
	set @name = trim(@name)

	if @name is null or len(@name) = 0
		return
	
	declare @db nvarchar(500)
	declare @schema nvarchar(500)
	declare @table nvarchar(500)
	declare @column nvarchar(500)

	declare @part1 nvarchar(500)
	declare @part2 nvarchar(500)
	declare @part3 nvarchar(500)
	declare @part4 nvarchar(500)

	select
		@part1 = parsename(@name, 4),
		@part2 = parsename(@name, 3),
		@part3 = parsename(@name, 2),
		@part4 = parsename(@name, 1)

	if @part1 is null and @part2 is null and @part3 is null
	begin
		set @schema = 'dbo'
		set @table = @part4
	end
	else
	if @part1 is null and @part2 is null
	begin
		set @schema = @part3
		set @table = @part4
	end
	else
	if @part1 is null
	begin
		set @db = @part2
		set @schema = @part3
		set @table = @part4
	end
	else
	begin
		set @db = @part1
		set @schema = @part2
		set @table = @part3
		set @column = @part4
	end

	insert into @result([db], [schema], [table], [column])
	values (@db, @schema, @table, @column)

	return
end
go


