-- ---------------------------------------------
-- functions/table_exists.sql
-- ---------------------------------------------
-- =============================================
-- mold.table_exists
-- =============================================
-- Returns 1 if the specified table exists, 0 otherwise.
--
-- Input formats:
--   'Products'             -> dbo.Products
--   'sales.Products'       -> sales.Products
--   'db.sales.Products'    -> db.sales.Products
--   '#tmp1'                -> tempdb..#tmp1
--   '##tmp2'               -> tempdb..##tmp2
--   '[sales].[My.Table]'   -> sales.[My.Table]
--
-- Unqualified names resolve to dbo (via parse_table_name).
-- Only user tables (type 'U') are recognized.
-- =============================================
CREATE OR ALTER FUNCTION mold.table_exists
(
    @name nvarchar(1000)
)
RETURNS bit
AS
BEGIN
    IF @name IS NULL OR LTRIM(RTRIM(@name)) = ''
        RETURN 0;

    DECLARE @normalized nvarchar(1000) = LTRIM(RTRIM(@name));

    -- Temp tables: parse_table_name returns schema = NULL and table = '#...'.
    -- Resolve them in tempdb explicitly.
    IF LEFT(@normalized, 1) = N'#'
    BEGIN
        RETURN CASE
            WHEN OBJECT_ID(N'tempdb..' + @normalized, N'U') IS NOT NULL THEN 1
            ELSE 0
        END;
    END

    -- Regular tables.
    DECLARE @db sysname, @schema sysname, @table sysname;

    SELECT
        @db     = ISNULL(p.[db], DB_NAME()),
        @schema = p.[schema],
        @table  = p.[table]
    FROM mold.parse_table_name(@normalized) p;

    -- parse_table_name returns schema = NULL only for temp tables
    -- (handled above). Any other NULL means an invalid input.
    IF @schema IS NULL OR @table IS NULL
        RETURN 0;

    DECLARE @full_name nvarchar(1000) =
        QUOTENAME(@db) + N'.' + QUOTENAME(@schema) + N'.' + QUOTENAME(@table);

    RETURN CASE
        WHEN OBJECT_ID(@full_name, N'U') IS NOT NULL THEN 1
        ELSE 0
    END;
END;
GO

go

-- ---------------------------------------------
-- functions/column_exists.sql
-- ---------------------------------------------
-- =============================================
-- mold.column_exists
-- =============================================
-- Returns 1 if the specified column exists on a user table, 0 otherwise.
--
-- Input formats:
--   'Table.Column'                  -> dbo.Table.Column
--   'Schema.Table.Column'           -> Schema.Table.Column
--   'Db.Schema.Table.Column'        -> Db.Schema.Table.Column
--   '[sales].[My.Table].[My.Column]'-> sales.[My.Table].[My.Column]
--
-- Temp tables are NOT supported (UDF limitation).
-- =============================================
CREATE OR ALTER FUNCTION mold.column_exists
(
    @name nvarchar(1000)
)
RETURNS bit
AS
BEGIN
    IF @name IS NULL OR LTRIM(RTRIM(@name)) = ''
        RETURN 0;

    DECLARE @db sysname, @schema sysname, @table sysname, @column sysname;

    SELECT
        @db     = ISNULL(p.[db], DB_NAME()),
        @schema = p.[schema],
        @table  = p.[table],
        @column = p.[column]
    FROM mold.parse_column_name(@name) p;

    -- For temp tables, parse_column_name returns schema = NULL and
    -- table = '#...'. Reject them (UDFs cannot access temp tables).
    IF @schema IS NULL OR @table IS NULL OR @column IS NULL
        RETURN 0;

    IF LEFT(@table, 1) = N'#'
        RETURN 0;

    DECLARE @full_name nvarchar(1000) =
        QUOTENAME(@db) + N'.' + QUOTENAME(@schema) + N'.' + QUOTENAME(@table);

    IF OBJECT_ID(@full_name, N'U') IS NULL
        RETURN 0;

    IF COL_LENGTH(@full_name, @column) IS NULL
        RETURN 0;

    RETURN 1;
END;
GO

go

-- ---------------------------------------------
-- functions/parse_column_type.sql
-- ---------------------------------------------
-- =============================================
-- mold.parse_column_type
-- =============================================
-- Parses a T-SQL type declaration string and returns a single row of
-- normalized metadata describing the type. Intended as the single
-- source of truth for type resolution inside create_column (and any
-- other helper that needs to reason about a column's declared type).
--
-- Accepts (whitespace- and bracket-tolerant):
--   'int'
--   'varchar(100)'
--   'nvarchar(max)'
--   'decimal(18,2)'
--   'datetime2(7)'
--   'uniqueidentifier'
--   '[dbo].[MyUdt]'
--   'varchar(100) NOT NULL'   -- trailing NULL / NOT NULL is stripped
--
-- Returns one row with:
--   input_type, base_type_name, type_schema, type_name, normalized_type,
--   args, arg1, arg2,
--   system_type_id, user_type_id, type_schema_id,
--   is_user_defined, is_table_type, is_assembly_type, collation_name,
--   is_max, char_length, byte_length, precision, scale, fractional_scale,
--   is_valid, validation_error
--
-- Notes:
--   - char_length is in CHARACTERS for nchar/nvarchar and BYTES otherwise.
--   - byte_length matches what sys.columns.max_length would store
--     (-1 for max); use it when comparing against column_info.max_length.
--   - is_valid = 0 when the base type is unknown, arguments are malformed,
--     or the type is a user-defined table type. Callers should THROW
--     using validation_error verbatim.
-- =============================================
CREATE OR ALTER FUNCTION mold.parse_column_type
(
    @type nvarchar(4000)
)
RETURNS TABLE
AS
RETURN
(
    WITH
    src AS
    (
        SELECT
            cleaned = LTRIM(RTRIM(
                          CASE
                              WHEN LTRIM(RTRIM(@type)) LIKE N'% NOT NULL'
                                  THEN LEFT(LTRIM(RTRIM(@type)), LEN(LTRIM(RTRIM(@type))) - 9)
                              WHEN LTRIM(RTRIM(@type)) LIKE N'% NULL'
                                  THEN LEFT(LTRIM(RTRIM(@type)), LEN(LTRIM(RTRIM(@type))) - 5)
                              ELSE LTRIM(RTRIM(@type))
                          END))
    ),
    split AS
    (
        SELECT
            base_name = LTRIM(RTRIM(
                            CASE WHEN CHARINDEX(N'(', s.cleaned) > 0
                                 THEN LEFT(s.cleaned, CHARINDEX(N'(', s.cleaned) - 1)
                                 ELSE s.cleaned END)),
            args      = CASE
                            WHEN CHARINDEX(N'(', s.cleaned) > 0
                                 AND RIGHT(s.cleaned, 1) = N')'
                                THEN SUBSTRING(s.cleaned,
                                               CHARINDEX(N'(', s.cleaned) + 1,
                                               LEN(s.cleaned) - CHARINDEX(N'(', s.cleaned) - 1)
                            ELSE NULL
                        END
        FROM src AS s
    ),
    norm AS
    (
        SELECT
            base_clean  = LTRIM(RTRIM(
                              CASE
                                  WHEN PARSENAME(REPLACE(REPLACE(split.base_name, N'[', N''), N']', N''), 2) IS NOT NULL
                                      THEN PARSENAME(REPLACE(REPLACE(split.base_name, N'[', N''), N']', N''), 1)
                                  ELSE REPLACE(REPLACE(split.base_name, N'[', N''), N']', N'')
                              END)),
            schema_part = CASE
                              WHEN PARSENAME(REPLACE(REPLACE(split.base_name, N'[', N''), N']', N''), 2) IS NOT NULL
                                  THEN PARSENAME(REPLACE(REPLACE(split.base_name, N'[', N''), N']', N''), 2)
                              ELSE NULL
                          END,
            args = split.args
        FROM split
    ),
    argsplit AS
    (
        SELECT
            n.base_clean,
            n.schema_part,
            n.args,
            p1 = CASE
                     WHEN n.args IS NULL THEN NULL
                     WHEN CHARINDEX(N',', n.args) > 0
                         THEN LTRIM(RTRIM(LEFT(n.args, CHARINDEX(N',', n.args) - 1)))
                     ELSE LTRIM(RTRIM(n.args))
                 END,
            p2 = CASE
                     WHEN n.args IS NULL THEN NULL
                     WHEN CHARINDEX(N',', n.args) > 0
                         THEN LTRIM(RTRIM(SUBSTRING(n.args, CHARINDEX(N',', n.args) + 1, 4000)))
                     ELSE NULL
                 END
        FROM norm AS n
    ),
    resolved AS
    (
        SELECT
            a.base_clean,
            a.schema_part,
            a.args,
            a.p1,
            a.p2,
            t.system_type_id,
            t.user_type_id,
            t.name        AS type_name,
            t.schema_id   AS type_schema_id,
            t.is_user_defined,
            t.is_table_type,
            t.is_assembly_type,
            t.max_length,
            t.precision,
            t.scale,
            t.collation_name
        FROM argsplit AS a
        OUTER APPLY
        (
            SELECT TOP (1) *
            FROM sys.types AS t
            WHERE t.name = a.base_clean
              AND (a.schema_part IS NULL OR t.schema_id = SCHEMA_ID(a.schema_part))
            ORDER BY
                t.is_user_defined ASC,
                CASE WHEN a.schema_part IS NOT NULL AND t.schema_id = SCHEMA_ID(a.schema_part) THEN 0 ELSE 1 END,
                CASE WHEN t.schema_id = SCHEMA_ID(N'dbo') THEN 0 ELSE 1 END
        ) AS t
    ),
    interpreted AS
    (
        SELECT
            r.base_clean,
            r.schema_part,
            r.args,
            r.p1,
            r.p2,
            r.system_type_id,
            r.user_type_id,
            r.type_name,
            r.type_schema_id,
            r.is_user_defined,
            r.is_table_type,
            r.is_assembly_type,
            r.collation_name,

            is_max = CASE WHEN LOWER(ISNULL(r.p1, N'')) = N'max' THEN 1 ELSE 0 END,

                        char_length =
                CASE
                    WHEN r.type_name IN (N'char', N'varchar', N'binary', N'varbinary') THEN
                        CASE
                            WHEN LOWER(ISNULL(r.p1, N'')) = N'max' THEN -1
                            WHEN r.p1 IS NOT NULL THEN TRY_CAST(r.p1 AS int)
                            ELSE 1                                  -- default length is 1
                        END
                    WHEN r.type_name IN (N'nchar', N'nvarchar') THEN
                        CASE
                            WHEN LOWER(ISNULL(r.p1, N'')) = N'max' THEN -1
                            WHEN r.p1 IS NOT NULL THEN TRY_CAST(r.p1 AS int)
                            ELSE 1                                  -- default length is 1 char
                        END
                    ELSE NULL
                END,

            num_precision =
                CASE
                    WHEN r.type_name IN (N'decimal', N'numeric') THEN
                        CASE WHEN r.p1 IS NOT NULL THEN TRY_CAST(r.p1 AS int)
                             ELSE r.precision END
                    WHEN r.type_name IN (N'tinyint', N'smallint', N'int', N'bigint',
                                         N'money', N'smallmoney', N'float', N'real',
                                         N'datetime', N'datetime2', N'datetimeoffset',
                                         N'time', N'bit')
                        THEN r.precision
                    ELSE NULL
                END,

            num_scale =
                CASE
                    WHEN r.type_name IN (N'decimal', N'numeric') THEN
                        CASE WHEN r.p2 IS NOT NULL THEN TRY_CAST(r.p2 AS int)
                             WHEN r.p1 IS NOT NULL THEN 0
                             ELSE r.scale END
                    WHEN r.type_name IN (N'datetime2', N'datetimeoffset', N'time') THEN
                        CASE WHEN r.p1 IS NOT NULL THEN TRY_CAST(r.p1 AS int)
                             ELSE r.scale END
                    WHEN r.type_name IN (N'money', N'smallmoney') THEN r.scale
                    ELSE NULL
                END,

            frac_scale =
                CASE
                    WHEN r.type_name IN (N'datetime2', N'datetimeoffset', N'time') THEN
                        CASE WHEN r.p1 IS NOT NULL THEN TRY_CAST(r.p1 AS int)
                             ELSE r.scale END
                    ELSE NULL
                END,

            byte_length =
                CASE
                    WHEN r.type_name IN (N'nchar', N'nvarchar') THEN
                        CASE
                            WHEN LOWER(ISNULL(r.p1, N'')) = N'max' THEN -1
                            WHEN r.p1 IS NOT NULL THEN TRY_CAST(r.p1 AS int) * 2
                            ELSE 2                                  -- 1 char = 2 bytes
                        END
                    WHEN r.type_name IN (N'char', N'varchar', N'binary', N'varbinary') THEN
                        CASE
                            WHEN LOWER(ISNULL(r.p1, N'')) = N'max' THEN -1
                            WHEN r.p1 IS NOT NULL THEN TRY_CAST(r.p1 AS int)
                            ELSE 1                                  -- default length is 1 byte
                        END
                    ELSE r.max_length
                END,

            has_unknown_base_type =
                CASE WHEN r.type_name IS NULL THEN 1 ELSE 0 END,

            has_bad_arg =
                CASE
                    WHEN r.args IS NULL THEN 0
                    WHEN r.type_name IN (N'char', N'varchar', N'nchar', N'nvarchar',
                                         N'binary', N'varbinary')
                         AND NOT (LOWER(r.p1) = N'max'
                                  OR (TRY_CAST(r.p1 AS int) IS NOT NULL AND TRY_CAST(r.p1 AS int) > 0))
                        THEN 1
                    WHEN r.type_name IN (N'decimal', N'numeric')
                         AND (TRY_CAST(r.p1 AS int) IS NULL
                              OR TRY_CAST(r.p1 AS int) NOT BETWEEN 1 AND 38
                              OR (r.p2 IS NOT NULL AND (TRY_CAST(r.p2 AS int) IS NULL OR TRY_CAST(r.p2 AS int) < 0))
                              OR (r.p2 IS NOT NULL AND TRY_CAST(r.p2 AS int) > TRY_CAST(r.p1 AS int)))
                        THEN 1
                    WHEN r.type_name IN (N'datetime2', N'datetimeoffset', N'time')
                         AND (TRY_CAST(r.p1 AS int) IS NULL OR TRY_CAST(r.p1 AS int) NOT BETWEEN 0 AND 7)
                        THEN 1
                    WHEN r.type_name NOT IN (N'char', N'varchar', N'nchar', N'nvarchar',
                                             N'binary', N'varbinary',
                                             N'decimal', N'numeric',
                                             N'datetime2', N'datetimeoffset', N'time')
                         AND r.p1 IS NOT NULL
                        THEN 1
                    ELSE 0
                END,

            normalized_type =
                CASE
                    WHEN r.type_name IS NULL THEN NULL

                        WHEN r.type_name IN (N'char', N'varchar', N'binary', N'varbinary') THEN
                            r.type_name + N'('
                            + (CASE
                                WHEN LOWER(ISNULL(r.p1, N'')) = N'max' THEN N'max'
                                WHEN r.p1 IS NOT NULL THEN r.p1
                                ELSE N'1'
                            END)
                            + N')'

                    WHEN r.type_name IN (N'nchar', N'nvarchar') THEN
                        r.type_name + N'('
                        + (CASE
                               WHEN LOWER(ISNULL(r.p1, N'')) = N'max' THEN N'max'
                               WHEN r.p1 IS NOT NULL THEN r.p1
                               ELSE N'1'
                           END)
                        + N')'

                    WHEN r.type_name IN (N'decimal', N'numeric') THEN
                        r.type_name + N'('
                        + CAST(ISNULL(TRY_CAST(r.p1 AS int), r.precision) AS nvarchar(20))
                        + N','
                        + CAST(ISNULL(TRY_CAST(r.p2 AS int), 0) AS nvarchar(20))
                        + N')'

                    WHEN r.type_name IN (N'datetime2', N'datetimeoffset', N'time') THEN
                        r.type_name + N'('
                        + CAST(ISNULL(TRY_CAST(r.p1 AS int), r.scale) AS nvarchar(20))
                        + N')'

                    WHEN r.is_user_defined = 1 AND r.schema_part IS NOT NULL THEN
                        QUOTENAME(r.schema_part) + N'.' + QUOTENAME(r.type_name)

                    ELSE r.type_name
                END
        FROM resolved AS r
    )
    SELECT
        input_type         = @type,

        base_type_name     = base_clean,
        type_schema        = schema_part,
        type_name          = type_name,
        normalized_type    = normalized_type,
        args               = args,
        arg1               = p1,
        arg2               = p2,

        system_type_id     = system_type_id,
        user_type_id       = user_type_id,
        type_schema_id     = type_schema_id,
        is_user_defined    = is_user_defined,
        is_table_type      = is_table_type,
        is_assembly_type   = is_assembly_type,
        collation_name     = collation_name,

        is_max             = is_max,
        char_length        = char_length,
        byte_length        = byte_length,
        precision          = num_precision,
        scale              = num_scale,
        fractional_scale   = frac_scale,

        is_valid           = CASE
                                 WHEN has_unknown_base_type = 1 THEN 0
                                 WHEN has_bad_arg = 1 THEN 0
                                 WHEN is_table_type = 1 THEN 0
                                 ELSE 1
                             END,
        validation_error   =
            CASE
                WHEN has_unknown_base_type = 1
                    THEN N'Unknown type name: ' + ISNULL(base_clean, N'(null)')
                WHEN is_table_type = 1
                    THEN N'User-defined table types cannot be used as column types: ' + base_clean
                WHEN has_bad_arg = 1
                    THEN N'Invalid argument(s) for type ' + base_clean + N': (' + ISNULL(args, N'') + N')'
                ELSE NULL
            END
    FROM interpreted
);
go


-- ---------------------------------------------
-- functions/column_dependencies.sql
-- ---------------------------------------------
-- =============================================
-- mold.column_dependencies
-- =============================================
-- Returns every dependency on a column: indexes, statistics, foreign keys
-- (on either side), computed columns, views, and other referencing modules.
--
-- Input formats:
--   'Table.Column'                  -> dbo.Table.Column
--   'Schema.Table.Column'           -> Schema.Table.Column
--   'Db.Schema.Table.Column'        -> Db.Schema.Table.Column
--   '[sales].[My.Table].[My.Column]'-> sales.[My.Table].[My.Column]
--
-- Returns:
--   dependency  nvarchar(1000)  -- object name (may be schema-qualified)
--   type        nvarchar(64)    -- 'index' | 'statistics' | 'foreign key' |
--                                 'computed column' | 'view' | 'module'
--
-- Notes:
--   - Primary key and unique constraints are reported as 'index' (the
--     underlying index is what blocks ALTER COLUMN).
--   - A column that participates in an FK is reported once per constraint,
--     with the constraint name, not the table name.
--   - `sys.sql_expression_dependencies` is the source for view and module
--     dependencies; it is authoritative for schema-bound objects and
--     best-effort for non-schema-bound ones.
-- =============================================
CREATE OR ALTER FUNCTION mold.column_dependencies
(
    @column nvarchar(1000)
)
RETURNS TABLE
AS
RETURN
(
    WITH
    parsed AS
    (
        SELECT [db], [schema], [table], [column]
        FROM mold.parse_column_name(@column)
    ),
    resolved AS
    (
        SELECT
            object_id  = OBJECT_ID(
                            QUOTENAME(ISNULL(p.[db], DB_NAME()))
                          + N'.' + QUOTENAME(ISNULL(p.[schema], N'dbo'))
                          + N'.' + QUOTENAME(p.[table])),
            column_id  = COLUMNPROPERTY(
                            OBJECT_ID(
                                QUOTENAME(ISNULL(p.[db], DB_NAME()))
                              + N'.' + QUOTENAME(ISNULL(p.[schema], N'dbo'))
                              + N'.' + QUOTENAME(p.[table])),
                            p.[column], 'ColumnId'),
            schema_name = ISNULL(p.[schema], N'dbo'),
            table_name  = p.[table],
            column_name = p.[column]
        FROM parsed AS p
    ),
    -- Indexes and statistics that reference the column. PK/unique constraints
    -- are reported as 'index' because that is what blocks ALTER COLUMN.
    idx AS
    (
        SELECT
            dependency = QUOTENAME(OBJECT_SCHEMA_NAME(i.object_id))
                       + N'.' + QUOTENAME(OBJECT_NAME(i.object_id))
                       + N'.' + QUOTENAME(i.name),
            type       = N'index'
        FROM resolved AS r
        JOIN sys.index_columns AS ic
             ON ic.object_id = r.object_id AND ic.column_id = r.column_id
        JOIN sys.indexes AS i
             ON i.object_id = ic.object_id AND i.index_id = ic.index_id
        WHERE i.type <> 0                          -- skip heaps
          AND i.is_hypothetical = 0
    ),
    stats AS
    (
        SELECT
            dependency = QUOTENAME(OBJECT_SCHEMA_NAME(s.object_id))
                       + N'.' + QUOTENAME(OBJECT_NAME(s.object_id))
                       + N'.' + QUOTENAME(s.name),
            type       = N'statistics'
        FROM resolved AS r
        JOIN sys.stats_columns AS sc
             ON sc.object_id = r.object_id AND sc.column_id = r.column_id
        JOIN sys.stats AS s
             ON s.object_id = sc.object_id AND s.stats_id = sc.stats_id
        -- user-created stats only; auto-created stats are not a dependency
        -- the user can act on and should not block ALTER COLUMN
        WHERE s.auto_created = 0
          AND s.user_created = 1
    ),
    fk AS
    (
        SELECT
            dependency = QUOTENAME(OBJECT_SCHEMA_NAME(fk.object_id))
                       + N'.' + QUOTENAME(OBJECT_NAME(fk.object_id))
                       + N'.' + QUOTENAME(fk.name),
            type       = N'foreign key'
        FROM resolved AS r
        JOIN sys.foreign_key_columns AS fkc
             ON (fkc.parent_object_id = r.object_id AND fkc.parent_column_id = r.column_id)
             OR (fkc.referenced_object_id = r.object_id AND fkc.referenced_column_id = r.column_id)
        JOIN sys.foreign_keys AS fk
             ON fk.object_id = fkc.constraint_object_id
    ),
    -- Computed columns in the same table that reference this column
    computed AS
    (
        SELECT
            dependency = QUOTENAME(OBJECT_SCHEMA_NAME(c.object_id))
                       + N'.' + QUOTENAME(OBJECT_NAME(c.object_id))
                       + N'.' + QUOTENAME(c.name),
            type       = N'computed column'
        FROM resolved AS r
        JOIN sys.sql_expression_dependencies AS d
             ON d.referenced_id = r.object_id
            AND d.referenced_minor_id = r.column_id
        JOIN sys.columns AS c
             ON c.object_id = d.referencing_id
            AND c.column_id = d.referencing_minor_id
        WHERE c.is_computed = 1
    ),
    -- Views and other modules (procs, functions, triggers) that reference
    -- the column. sys.sql_expression_dependencies covers schema-bound
    -- objects and is best-effort for non-schema-bound ones.
    modules AS
    (
        SELECT
            dependency = QUOTENAME(OBJECT_SCHEMA_NAME(d.referencing_id))
                       + N'.' + QUOTENAME(OBJECT_NAME(d.referencing_id)),
            type       = CASE o.type
                             WHEN N'V' THEN N'view'
                             WHEN N'P' THEN N'module'
                             WHEN N'FN' THEN N'module'
                             WHEN N'IF' THEN N'module'
                             WHEN N'TF' THEN N'module'
                             WHEN N'TR' THEN N'module'
                             ELSE N'module'
                         END
        FROM resolved AS r
        JOIN sys.sql_expression_dependencies AS d
             ON d.referenced_id = r.object_id
            AND d.referenced_minor_id = r.column_id
        JOIN sys.objects AS o
             ON o.object_id = d.referencing_id
        WHERE o.type IN (N'V', N'P', N'FN', N'IF', N'TF', N'TR')
    ),
    all_deps AS
    (
        SELECT dependency, type FROM idx
        UNION ALL
        SELECT dependency, type FROM stats
        UNION ALL
        SELECT dependency, type FROM fk
        UNION ALL
        SELECT dependency, type FROM computed
        UNION ALL
        SELECT dependency, type FROM modules
    )
    SELECT
        dependency,
        type
    FROM all_deps
    WHERE dependency IS NOT NULL
);
GO

go

-- ---------------------------------------------
-- functions/column_type_change.sql
-- ---------------------------------------------
-- =============================================
-- mold.column_type_change
-- =============================================
-- Classifies a proposed type change and reports what, if anything, must be
-- verified before ALTER COLUMN can run.
--
-- Both source and target are described by:
--   @type_name   -- canonical name from sys.types (e.g. 'int', 'varchar')
--   @length      -- sys.columns.max_length semantics (-1 for max)
--   @precision   -- sys.columns.precision (NULL for non-numeric)
--   @scale       -- sys.columns.scale (NULL for non-numeric/non-temporal)
--
-- Returns a single row:
--   class                    'widening' | 'narrowing' | 'lateral' | 'forbidden'
--   requires_data_check      1 when existing rows must be verified to fit the target
--   requires_collation_check 1 when the code page / collation changes
--   reason                   human-readable summary (NULL for widening)
--
-- Classification:
--   widening   target domain superset of source; no data check needed
--   narrowing  target domain subset; rows must be verified to fit
--   lateral    same family but encoding or collation changes (n<->varchar);
--              always requires a data check, and a collation check when the
--              target is the non-Unicode side
--   forbidden  different type family, or a change SQL Server will not accept
--
-- Notes:
--   - @length follows sys.columns.max_length: -1 means MAX, and nchar/nvarchar
--     lengths are in BYTES (2 per character). The comparison logic divides by
--     two where the domain is defined in characters.
--   - The function only classifies; it does not query data. The caller performs
--     the data and collation checks named by the returned flags.
-- =============================================
CREATE OR ALTER FUNCTION mold.column_type_change
(
    @from_type      nvarchar(128),
    @from_length    int,
    @from_precision int,
    @from_scale     int,
    @to_type        nvarchar(128),
    @to_length      int,
    @to_precision   int,
    @to_scale       int
)
RETURNS TABLE
AS
RETURN
(
    WITH
    norm AS
    (
        SELECT
            f_type   = @from_type,
            t_type   = @to_type,

            f_chars  = CASE
                           WHEN @from_type IN (N'nchar', N'nvarchar')
                               THEN CASE WHEN @from_length = -1 THEN -1
                                         ELSE @from_length / 2 END
                           WHEN @from_type IN (N'char', N'varchar', N'binary', N'varbinary')
                               THEN @from_length
                           ELSE NULL
                       END,
            t_chars  = CASE
                           WHEN @to_type IN (N'nchar', N'nvarchar')
                               THEN CASE WHEN @to_length = -1 THEN -1
                                         ELSE @to_length / 2 END
                           WHEN @to_type IN (N'char', N'varchar', N'binary', N'varbinary')
                               THEN @to_length
                           ELSE NULL
                       END,

            f_int_digits = CASE
                               WHEN @from_type IN (N'decimal', N'numeric')
                                   THEN @from_precision - @from_scale
                               ELSE NULL
                           END,
            t_int_digits = CASE
                               WHEN @to_type IN (N'decimal', N'numeric')
                                   THEN @to_precision - @to_scale
                               ELSE NULL
                           END
    ),
    classify AS
    (
        SELECT
            n.*,

            is_int_family  = CASE WHEN n.f_type IN (N'tinyint', N'smallint', N'int', N'bigint')
                                   AND n.t_type IN (N'tinyint', N'smallint', N'int', N'bigint')
                                  THEN 1 ELSE 0 END,

            int_rank_f     = CASE n.f_type WHEN N'tinyint' THEN 1 WHEN N'smallint' THEN 2
                                           WHEN N'int' THEN 3 WHEN N'bigint' THEN 4 END,
            int_rank_t     = CASE n.t_type WHEN N'tinyint' THEN 1 WHEN N'smallint' THEN 2
                                           WHEN N'int' THEN 3 WHEN N'bigint' THEN 4 END,

            is_char_family = CASE WHEN n.f_type IN (N'char', N'varchar', N'nchar', N'nvarchar')
                                  THEN 1 ELSE 0 END,
            is_char_to     = CASE WHEN n.t_type IN (N'char', N'varchar', N'nchar', N'nvarchar')
                                  THEN 1 ELSE 0 END,
            same_char_fam  = CASE WHEN (n.f_type IN (N'char', N'nchar')
                                        AND n.t_type IN (N'char', N'nchar'))
                                   OR (n.f_type IN (N'varchar', N'nvarchar')
                                        AND n.t_type IN (N'varchar', N'nvarchar'))
                                  THEN 1 ELSE 0 END,
            fixed_to_var   = CASE WHEN (n.f_type = N'char'    AND n.t_type = N'varchar')
                                   OR (n.f_type = N'nchar'   AND n.t_type = N'nvarchar')
                                   OR (n.f_type = N'binary'  AND n.t_type = N'varbinary')
                                  THEN 1 ELSE 0 END,
            var_to_fixed   = CASE WHEN (n.f_type = N'varchar'    AND n.t_type = N'char')
                                   OR (n.f_type = N'nvarchar'   AND n.t_type = N'nchar')
                                   OR (n.f_type = N'varbinary'  AND n.t_type = N'binary')
                                  THEN 1 ELSE 0 END,

            is_bin_family  = CASE WHEN n.f_type IN (N'binary', N'varbinary')
                                   AND n.t_type IN (N'binary', N'varbinary')
                                  THEN 1 ELSE 0 END,

            is_dec_family  = CASE WHEN n.f_type IN (N'decimal', N'numeric')
                                   AND n.t_type IN (N'decimal', N'numeric')
                                  THEN 1 ELSE 0 END,

            is_dt2_family  = CASE WHEN n.f_type = n.t_type
                                   AND n.t_type IN (N'datetime2', N'datetimeoffset', N'time')
                                  THEN 1 ELSE 0 END,
            is_dt_family   = CASE WHEN n.f_type IN (N'smalldatetime', N'datetime', N'datetime2')
                                   AND n.t_type IN (N'smalldatetime', N'datetime', N'datetime2')
                                  THEN 1 ELSE 0 END,
            dt_rank_f      = CASE n.f_type WHEN N'smalldatetime' THEN 1 WHEN N'datetime' THEN 2
                                           WHEN N'datetime2' THEN 3 END,
            dt_rank_t      = CASE n.t_type WHEN N'smalldatetime' THEN 1 WHEN N'datetime' THEN 2
                                           WHEN N'datetime2' THEN 3 END,

            is_float_family = CASE WHEN n.f_type IN (N'real', N'float')
                                    AND n.t_type IN (N'real', N'float')
                                   THEN 1 ELSE 0 END,

            is_money_family = CASE WHEN n.f_type = n.t_type
                                    AND n.f_type IN (N'money', N'smallmoney')
                                   THEN 1 ELSE 0 END,
            money_rank_f    = CASE n.f_type WHEN N'smallmoney' THEN 1 WHEN N'money' THEN 2 END,
            money_rank_t    = CASE n.t_type WHEN N'smallmoney' THEN 1 WHEN N'money' THEN 2 END
        FROM norm AS n
    ),
    verdict AS
    (
        SELECT
            c.*,

            class = CASE

                -- ---------- identity ----------
                WHEN c.f_type = c.t_type AND c.f_type IN (
                     N'int', N'bigint', N'smallint', N'tinyint', N'bit',
                     N'uniqueidentifier', N'date', N'xml',
                     N'varchar', N'nvarchar', N'char', N'nchar',
                     N'binary', N'varbinary', N'real', N'float',
                     N'money', N'smallmoney', N'datetime', N'smalldatetime',
                     N'datetime2', N'datetimeoffset', N'time',
                     N'decimal', N'numeric')
                     AND (
                         (c.f_chars IS NULL AND c.t_chars IS NULL)
                         OR (c.f_chars IS NOT NULL AND c.f_chars = c.t_chars)
                         OR (c.f_chars = -1 AND c.t_chars = -1)
                     )
                     AND ISNULL(c.f_int_digits, -1)  = ISNULL(c.t_int_digits, -1)
                     AND ISNULL(@from_scale, -1)     = ISNULL(@to_scale, -1)
                    THEN N'widening'

                -- ---------- integer family ----------
                WHEN c.is_int_family = 1
                    THEN CASE
                             WHEN c.int_rank_t >= c.int_rank_f THEN N'widening'
                             ELSE N'narrowing'
                         END

                -- ---------- character family ----------
                WHEN c.is_char_family = 1 AND c.is_char_to = 1
                    THEN CASE

                        WHEN c.f_type = c.t_type THEN
                            CASE
                                WHEN c.f_chars = -1 AND c.t_chars = -1 THEN N'widening'
                                WHEN c.f_chars = -1 THEN N'narrowing'
                                WHEN c.t_chars = -1 THEN N'widening'
                                WHEN c.t_chars >= c.f_chars THEN N'widening'
                                ELSE N'narrowing'
                            END

                        WHEN c.fixed_to_var = 1 THEN
                            CASE
                                WHEN c.t_chars = -1 THEN N'widening'
                                WHEN c.t_chars >= c.f_chars THEN N'widening'
                                ELSE N'narrowing'
                            END

                        WHEN c.var_to_fixed = 1 THEN N'narrowing'

                        WHEN c.same_char_fam = 1 THEN
                            CASE
                                WHEN c.f_type IN (N'char', N'varchar')
                                    AND c.t_type IN (N'nchar', N'nvarchar')
                                    AND (c.t_chars = -1 OR (c.f_chars <> -1 AND c.t_chars >= c.f_chars))
                                    THEN N'widening'
                                WHEN c.f_type IN (N'nchar', N'nvarchar')
                                    AND c.t_type IN (N'char', N'varchar')
                                    THEN N'lateral'

                                ELSE N'narrowing'
                            END

                        WHEN c.f_type = N'char' AND c.t_type = N'nvarchar' THEN
                            CASE
                                WHEN c.t_chars = -1 THEN N'widening'
                                WHEN c.f_chars <> -1 AND c.t_chars >= c.f_chars
                                    THEN N'widening'
                                ELSE N'narrowing'
                            END

                        ELSE N'forbidden'
                    END

                -- ---------- binary family ----------
                WHEN c.is_bin_family = 1
                    THEN CASE
                        WHEN c.f_type = N'binary'    AND c.t_type = N'varbinary'
                             AND (c.t_chars = -1 OR c.t_chars >= c.f_chars) THEN N'widening'
                        WHEN c.f_type = N'varbinary' AND c.t_type = N'binary'
                             THEN N'narrowing'
                        WHEN c.f_type = c.t_type THEN
                            CASE
                                WHEN c.f_chars = -1 AND c.t_chars = -1 THEN N'widening'
                                WHEN c.f_chars = -1 THEN N'narrowing'
                                WHEN c.t_chars = -1 THEN N'widening'
                                WHEN c.t_chars >= c.f_chars THEN N'widening'
                                ELSE N'narrowing'
                            END
                        ELSE N'forbidden'
                    END

                -- ---------- decimal family ----------
                WHEN c.is_dec_family = 1
                    THEN CASE
                        WHEN c.t_int_digits >= c.f_int_digits
                             AND @to_scale >= @from_scale
                            THEN N'widening'
                        ELSE N'narrowing'
                    END

                -- ---------- temporal precision family ----------
                WHEN c.is_dt2_family = 1
                    THEN CASE
                        WHEN @to_scale >= @from_scale THEN N'widening'
                        ELSE N'narrowing'
                    END

                -- ---------- temporal family ----------
                WHEN c.is_dt_family = 1
                    THEN CASE
                        WHEN c.dt_rank_t >= c.dt_rank_f THEN N'widening'
                        ELSE N'narrowing'
                    END

                -- ---------- float family ----------
                WHEN c.is_float_family = 1
                    THEN CASE
                        WHEN c.f_type = N'real' AND c.t_type = N'float' THEN N'widening'
                        WHEN c.f_type = c.t_type THEN N'widening'
                        ELSE N'narrowing'
                    END

                -- ---------- money family ----------
                WHEN c.is_money_family = 1
                    THEN CASE
                        WHEN c.money_rank_t >= c.money_rank_f THEN N'widening'
                        ELSE N'narrowing'
                    END

                -- ---------- money <-> decimal ----------
                WHEN c.f_type = N'money' AND c.t_type IN (N'decimal', N'numeric')
                    THEN CASE
                        WHEN c.t_int_digits >= 15 AND @to_scale >= 4 THEN N'widening'
                        ELSE N'narrowing'
                    END

                ELSE N'forbidden'
            END
        FROM classify AS c
    )
    SELECT
        class = v.class,

        requires_data_check = CASE
            WHEN v.class IN (N'narrowing', N'lateral') THEN 1
            ELSE 0
        END,

        requires_collation_check = CASE
            WHEN v.f_type IN (N'nchar', N'nvarchar')
                 AND v.t_type IN (N'char', N'varchar')
                THEN 1
            WHEN v.f_type IN (N'char', N'varchar')
                 AND v.t_type IN (N'nchar', N'nvarchar')
                THEN 1
            ELSE 0
        END,

        reason = CASE
            WHEN v.class = N'forbidden'
                THEN N'type change from ' + v.f_type + N' to ' + v.t_type
                   + N' is not supported; use a manual migration.'
            WHEN v.class = N'narrowing'
                THEN N'target type is narrower than the source; '
                   + N'existing values must fit the new domain.'
            WHEN v.class = N'lateral'
                THEN N'Unicode to non-Unicode conversion may lose characters; '
                   + N'an explicit target collation and a data check are required.'
            ELSE NULL
        END
    FROM verdict AS v
);
GO

go

-- ---------------------------------------------
-- procedures/create_default.sql
-- ---------------------------------------------
-- =============================================
-- mold.create_default
-- =============================================
-- Creates or syncs a DEFAULT constraint on a column.
--
-- Behavior:
--   - If the column already has a default with the same (normalized)
--     value, this is a no-op.
--   - If the column has a default with a different value, the old
--     constraint is dropped and a new one is created.
--   - If the column has no default, a new constraint is created.
--   - If the table or column does not exist, an error is raised.
--
-- Parameters:
--   @column  Column reference: 'Table.Column', 'Schema.Table.Column',
--            'Db.Schema.Table.Column', '[sales].[My.Table].[Col]', etc.
--   @value   SQL expression for the default (e.g. '0', N''hello'',
--            'getdate()', '' for empty string). It is inserted verbatim
--            into the ALTER statement; the caller is responsible for
--            quoting strings.
--   @name    Optional constraint name. If NULL, the default name is
--            DF_<table>_<column>.
-- =============================================
CREATE OR ALTER PROCEDURE mold.create_default
(
    @column nvarchar(1000),
    @value  nvarchar(max),
    @name   sysname = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    -- ---------------------------------------------------------
    -- 1. Validate inputs.
    -- ---------------------------------------------------------
    IF @column IS NULL OR LTRIM(RTRIM(@column)) = N''
    BEGIN
        RAISERROR('create_default: @column is required.', 16, 1);
        RETURN;
    END

    IF @value IS NULL
    BEGIN
        RAISERROR('create_default: @value is required.', 16, 1);
        RETURN;
    END

    -- ---------------------------------------------------------
    -- 2. Parse the column reference.
    -- ---------------------------------------------------------
    DECLARE @db sysname, @schema sysname, @table sysname, @col sysname;

    SELECT
        @db     = ISNULL(p.[db], DB_NAME()),
        @schema = p.[schema],
        @table  = p.[table],
        @col    = p.[column]
    FROM mold.parse_column_name(@column) p;

    IF @db IS NULL OR @schema IS NULL OR @table IS NULL OR @col IS NULL
    BEGIN
        RAISERROR('create_default: invalid column reference "%s".', 16, 1, @column);
        RETURN;
    END

    -- ---------------------------------------------------------
    -- 3. Verify the table and column exist.
    -- ---------------------------------------------------------
    DECLARE @full_name nvarchar(1000) =
        QUOTENAME(@db) + N'.' + QUOTENAME(@schema) + N'.' + QUOTENAME(@table);

    DECLARE @table_id int = OBJECT_ID(@full_name, N'U');
    IF @table_id IS NULL
    BEGIN
        RAISERROR('create_default: table "%s" does not exist.', 16, 1, @full_name);
        RETURN;
    END

    IF NOT EXISTS (
        SELECT 1 FROM sys.columns
        WHERE object_id = @table_id AND name = @col
    )
    BEGIN
        RAISERROR('create_default: column "%s" does not exist on "%s".', 16, 1, @col, @full_name);
        RETURN;
    END

    -- ---------------------------------------------------------
    -- 4. Look up the existing default (name + definition) in one go.
    -- ---------------------------------------------------------
    DECLARE @existing_constraint sysname;
    DECLARE @existing_definition nvarchar(max);

    SELECT
        @existing_constraint = dc.name,
        @existing_definition = dc.definition
    FROM sys.default_constraints dc
    JOIN sys.columns c
      ON c.object_id = dc.parent_object_id
     AND c.column_id = dc.parent_column_id
    WHERE dc.parent_object_id = @table_id
      AND c.name = @col;

    IF @existing_constraint IS NOT NULL
    BEGIN
        DECLARE @actual_norm   nvarchar(max) = mold._normalize_default(@existing_definition);
        DECLARE @expected_norm nvarchar(max) = mold._normalize_default(@value);

        -- 4a. Same value: no-op.
        IF @actual_norm = @expected_norm
        BEGIN
            PRINT 'create_default: default already exists; nothing to do.';
            RETURN;
        END

        -- 4b. Different value: drop the old constraint.
        DECLARE @drop_sql nvarchar(max) =
            N'ALTER TABLE ' + @full_name
          + N' DROP CONSTRAINT ' + QUOTENAME(@existing_constraint) + N';';
        EXEC sp_executesql @drop_sql;
        PRINT 'create_default: dropped existing constraint "' + @existing_constraint + '".';
    END

    -- ---------------------------------------------------------
    -- 5. Determine the constraint name.
    -- ---------------------------------------------------------
    DECLARE @constraint_name sysname =
        ISNULL(@name, N'DF_' + @table + N'_' + @col);

    -- ---------------------------------------------------------
    -- 6. Create the new default constraint.
    -- ---------------------------------------------------------
    DECLARE @add_sql nvarchar(max) =
        N'ALTER TABLE ' + @full_name
      + N' ADD CONSTRAINT ' + QUOTENAME(@constraint_name)
      + N' DEFAULT ' + @value
      + N' FOR ' + QUOTENAME(@col) + N';';
    EXEC sp_executesql @add_sql;

    PRINT 'create_default: created constraint "' + @constraint_name + '" on '
        + @full_name + N'.' + QUOTENAME(@col) + '.';
END;
GO

go

-- ---------------------------------------------
-- procedures/create_column.sql
-- ---------------------------------------------
-- =============================================
-- mold.create_column
-- =============================================
-- Creates or converges a column on a table from a JSON spec. Idempotent:
-- re-running with the same @spec is safe and produces no side effects.
--
-- Input:
--   @spec  JSON document with the following shape:
--
--   {
--     "table":        "sales.Products",          -- required, dotted name
--     "name":         "DiscountPrice",           -- required
--     "type":         "int",                     -- required unless "computed"
--     "nullable":     true,                      -- optional, default false
--     "sparse":       true,                      -- optional, default false
--     "identity":     { "seed": 1, "increment": 1 },  -- optional
--     "default":      "0",                       -- optional, SQL expression
--     "default_name": "DF_Products_DiscountPrice",-- optional
--     "computed":     { "expression": "Qty * Price", "persisted": true }, -- optional
--     "dryRun":       false,                     -- optional, default false
--     "timeout":      10000                      -- optional, lock timeout ms
--   }
--
--   "type" follows T-SQL declaration syntax and is parsed by parse_column_type
--   (e.g. 'varchar(100)', 'decimal(18,2)', 'nvarchar(max)', 'datetime2(7)').
--   When "computed" is supplied, "type" and the identity/sparse/default fields
--   are ignored; the computed expression and persisted flag are the contract.
--
-- Result:
--   Returns one row:  status, detail
--     status  'CREATED' | 'ALTERED' | 'NO CHANGE' | 'DRY RUN'
--     detail  human-readable summary, or the T-SQL that would be run for
--             a dry run. On error, no row is returned; the caller gets a
--             THROW instead. The status row is the pipeline's control
--             signal; informational messages are returned only through
--             this result row (no duplicate message-stream output).
--
-- Behavior:
--   CREATE  (column absent)
--     Adds the column with type, nullable, sparse, identity, computed,
--     and default (if supplied) in one ALTER TABLE.
--
--   ALTER   (column present)
--     - type       : widening, narrowing (with data check), or lateral
--                    nvarchar<->varchar (with data and collation checks),
--                    as classified by column_type_change. Family changes
--                    and unsupported conversions are refused.
--     - nullable   : toggled; NULL -> NOT NULL scans existing rows first.
--     - sparse     : toggled.
--     - default    : added or replaced only when "default" is supplied;
--                    delegated to create_default inside the same
--                    transaction and lock.
--     - identity   : must match the existing column; cannot be added to
--                    or removed from an existing column.
--     - computed   : expression and persisted flag must match the
--                    existing column; the formula cannot be changed.
--
--   The default is never touched when "default" is absent from @spec,
--   even if the column currently has one. To remove a default, use
--   drop_default explicitly.
--
-- Safety:
--   - sp_getapplock on db.schema.table, exclusive, for the duration of
--     the transaction. Concurrent create_column calls on the same table
--     serialize instead of racing.
--   - Uses a transaction when called standalone, or a savepoint when called
--     inside a caller-owned transaction. It commits/rolls back only a
--     transaction it started; caller-owned transactions remain caller-owned.
--   - Any committable failure rolls back this helper's work. If a caller-owned
--     transaction becomes uncommittable, the caller must roll it back.
--   - Column dependencies (index, FK, computed column, view, module) are
--     detected via column_dependencies and refuse the ALTER with a
--     message naming the blocker. Drop or alter the dependent object
--     first, or apply the change manually.
--
-- Reserved error states:
--   50000  invalid @spec (missing table/name/type)
--   50001  target table does not exist
--   50002  invalid type declaration
--   50003  could not acquire app lock within timeout
--   50010  column has a blocking dependency
--   50011  existing column is IDENTITY; cannot convert
--   50012  existing column is not IDENTITY; cannot convert
--   50013  existing column is computed; cannot convert
--   50014  existing column is not computed; cannot convert
--   50015  computed expression differs from existing column
--   50016  type change is forbidden (different family or unsupported)
--   50017  existing rows would not fit the target type or NOT NULL
--   50018  Unicode-to-non-Unicode change requires an explicit COLLATE
--   50019  specified collation matches the current one (no-op change)
--   50020  caller transaction is not committable
--
-- Examples:
--   EXEC m.create_column @spec = N'{
--     "table": "sales.Products",
--     "name": "DiscountPrice",
--     "type": "int",
--     "nullable": true,
--     "default": "0"
--   }';
--
--   EXEC m.create_column @spec = N'{
--     "table": "sales.Products",
--     "name": "Total",
--     "computed": { "expression": "Qty * Price", "persisted": true }
--   }';
--
--   EXEC m.create_column @spec = N'{
--     "table": "sales.Products",
--     "name": "Notes",
--     "type": "nvarchar(500)",
--     "nullable": true,
--     "dryRun": true
--   }';
-- =============================================
SET ANSI_NULLS ON;
GO

SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE mold.create_column
(
    @spec nvarchar(max)
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT OFF;

    ------------------------------------------------------------------
    -- 1. Parse @spec
    ------------------------------------------------------------------
    DECLARE @table        nvarchar(1000),
            @name         nvarchar(500),
            @type         nvarchar(4000),
            @nullable     bit = 0,
            @sparse       bit = 0,
            @default      nvarchar(max),
            @default_name nvarchar(500),
            @identity     bit = 0,
            @seed         bigint,
            @increment    bigint,
            @computed     bit = 0,
            @expression   nvarchar(max),
            @persisted    bit = 0,
            @dry_run      bit = 0,
            @timeout      int = 10000;

    BEGIN TRY
        SELECT
            @table        = j.[table],
            @name         = j.[name],
            @type         = j.[type],
            @nullable     = ISNULL(j.[nullable], 0),
            @sparse       = ISNULL(j.[sparse], 0),
            @default      = j.[default],
            @default_name = j.default_name,
            @identity     = CASE WHEN j.[identity] IS NOT NULL THEN 1 ELSE 0 END,
            @seed         = TRY_CAST(JSON_VALUE(@spec, '$.identity.seed')      AS bigint),
            @increment    = TRY_CAST(JSON_VALUE(@spec, '$.identity.increment') AS bigint),
            @computed     = CASE WHEN j.computed IS NOT NULL THEN 1 ELSE 0 END,
            @expression   = JSON_VALUE(@spec, '$.computed.expression'),
            @persisted    = ISNULL(TRY_CAST(JSON_VALUE(@spec, '$.computed.persisted') AS bit), 0),
            @dry_run      = ISNULL(TRY_CAST(JSON_VALUE(@spec, '$.dryRun')  AS bit), 0),
            @timeout      = ISNULL(TRY_CAST(JSON_VALUE(@spec, '$.timeout') AS int), 10000)
        FROM OPENJSON(@spec)
        WITH
        (
            [table]        nvarchar(1000) '$.table',
            [name]         nvarchar(500)  '$.name',
            [type]         nvarchar(4000) '$.type',
            [nullable]     bit            '$.nullable',
            [sparse]       bit            '$.sparse',
            [default]      nvarchar(max)  '$.default',
            default_name   nvarchar(500)  '$.default_name',
            [identity]     nvarchar(max)  '$.identity'   AS JSON,
            computed       nvarchar(max)  '$.computed'   AS JSON
        ) AS j;

        IF @table IS NULL OR @name IS NULL
        BEGIN
            ;THROW 50000, N'create_column: @spec must contain "table" and "name".', 1;
        END

        IF @computed = 0 AND @type IS NULL
        BEGIN
            ;THROW 50000, N'create_column: @spec must contain "type" unless "computed" is provided.', 1;
        END

        ------------------------------------------------------------------
        -- 2. Resolve names, validate table
        ------------------------------------------------------------------
        DECLARE @db     sysname, @schema sysname, @tbl sysname;

        SELECT @db = [db], @schema = [schema], @tbl = [table]
        FROM mold.parse_table_name(@table);

        IF @db IS NULL SET @db = DB_NAME();
        IF @schema IS NULL SET @schema = N'dbo';

        IF mold.table_exists(@table) = 0
        BEGIN
            ;THROW 50001, N'create_column: target table does not exist.', 1;
        END

        DECLARE @full_table  nvarchar(1500) = QUOTENAME(@schema) + N'.' + QUOTENAME(@tbl);
        DECLARE @full_column nvarchar(1500) = @full_table + N'.' + QUOTENAME(@name);

        ------------------------------------------------------------------
        -- 3. Validate type (unless computed)
        ------------------------------------------------------------------
        DECLARE @t TABLE (
            normalized_type  nvarchar(4000),
            type_name        nvarchar(500),
            system_type_id   int,
            user_type_id     int,
            is_user_defined  bit,
            is_valid         bit,
            validation_error nvarchar(max),
            collation_name   nvarchar(500),
            char_length      int,
            byte_length      int,
            precision        int,
            scale            int,
            fractional_scale int
        );

        IF @computed = 0
        BEGIN
            INSERT @t
            SELECT
                normalized_type,
                type_name,
                system_type_id,
                user_type_id,
                is_user_defined,
                is_valid,
                validation_error,
                collation_name,
                char_length,
                byte_length,
                precision,
                scale,
                fractional_scale
            FROM mold.parse_column_type(@type);

            IF (SELECT is_valid FROM @t) = 0
            BEGIN
                DECLARE @msg_type nvarchar(2048) =
                    N'create_column: ' + ISNULL((SELECT validation_error FROM @t), N'invalid type.');
                ;THROW 50002, @msg_type, 1;
            END
        END

        ------------------------------------------------------------------
        -- 4. Applock + transaction
        ------------------------------------------------------------------
        DECLARE @lock_resource nvarchar(255) =
            N'create_column:' + QUOTENAME(@db) + N'.' + QUOTENAME(@schema) + N'.' + QUOTENAME(@tbl);

        DECLARE @lock_rc int;
        DECLARE @started_transaction bit = 0;
        DECLARE @savepoint_created bit = 0;

        BEGIN TRY
            -- Respect a transaction owned by the caller. A savepoint lets
            -- this procedure undo its own work without rolling back the
            -- caller's transaction.
            IF @@TRANCOUNT = 0
            BEGIN
                BEGIN TRANSACTION;
                SET @started_transaction = 1;
            END
            ELSE
            BEGIN
                IF XACT_STATE() <> 1
                BEGIN
                    ;THROW 50020, N'create_column: the caller transaction is not committable.', 1;
                END

                SAVE TRANSACTION create_column_savepoint;
                SET @savepoint_created = 1;
            END

            -- Transaction-owned application locks require an active
            -- transaction, so acquire the lock only after transaction setup.
            EXEC @lock_rc = sp_getapplock
                 @Resource    = @lock_resource,
                 @LockMode    = N'Exclusive',
                 @LockOwner   = N'Transaction',
                 @LockTimeout = @timeout;

            IF @lock_rc < 0
            BEGIN
                ;THROW 50003, N'create_column: could not acquire lock within timeout.', 1;
            END
            ------------------------------------------------------------------
            -- 5. CREATE path
            ------------------------------------------------------------------
            IF mold.column_exists(@full_column) = 0
            BEGIN
                DECLARE @ddl nvarchar(max) =
                    N'ALTER TABLE ' + @full_table + N' ADD ' + QUOTENAME(@name) + N' ';

                IF @computed = 1
                BEGIN
                    SET @ddl += N'AS (' + @expression + N')'
                             + CASE WHEN @persisted = 1 THEN N' PERSISTED' ELSE N'' END;
                END
                ELSE
                BEGIN
                    SET @ddl += (SELECT normalized_type FROM @t)
                             + CASE WHEN @identity = 1
                                        THEN N' IDENTITY(' + CAST(ISNULL(@seed, 1) AS nvarchar(20))
                                             + N',' + CAST(ISNULL(@increment, 1) AS nvarchar(20)) + N')'
                                        ELSE N'' END
                             + CASE WHEN @sparse = 1 THEN N' SPARSE' ELSE N'' END
                             + CASE WHEN @nullable = 1 THEN N' NULL' ELSE N' NOT NULL' END
                             + CASE WHEN @default IS NOT NULL
                                        THEN N' CONSTRAINT ' + QUOTENAME(ISNULL(@default_name, N'DF_' + @tbl + N'_' + @name))
                                             + N' DEFAULT ' + @default
                                        ELSE N'' END;
                END

                IF @dry_run = 1
                BEGIN
                    IF @started_transaction = 1
                        COMMIT TRANSACTION;

                    SELECT status = N'DRY RUN', detail = @ddl;
                    RETURN;
                END

                EXEC sp_executesql @ddl;

                IF @started_transaction = 1
                    COMMIT TRANSACTION;

                DECLARE @msg_new nvarchar(4000) = N'create_column: ' + @full_column + N' -> CREATED';

                SELECT status = N'CREATED', detail = N'column added';
                RETURN;
            END

            ------------------------------------------------------------------
            -- 6. ALTER path: read current state
            ------------------------------------------------------------------
            DECLARE @ci TABLE (
                type_name            nvarchar(500),
                system_type_id       int,
                user_type_id         int,
                max_length           int,
                [precision]          int,
                scale                int,
                collation_name       nvarchar(500),
                is_nullable          bit,
                is_identity          bit,
                is_computed          bit,
                is_sparse            bit,
                default_value   nvarchar(max),
                computed_definition  nvarchar(max)
            );

            INSERT @ci
            SELECT
                type_name,
                system_type_id,
                user_type_id,
                max_length,
                [precision],
                scale,
                collation_name,
                is_nullable,
                is_identity,
                is_computed,
                is_sparse,
                default_value,
                computed_definition
            FROM mold.column_info(@full_column);

            DECLARE @cur TABLE (
                type_name           nvarchar(500),
                system_type_id      int,
                max_length          int,
                [precision]         int,
                scale               int,
                collation_name      nvarchar(500),
                is_nullable         bit,
                is_identity         bit,
                is_computed         bit,
                is_sparse           bit,
                default_value       nvarchar(max),
                computed_definition nvarchar(max)
            );
            INSERT @cur
            SELECT
                type_name,
                system_type_id,
                max_length,
                [precision],
                scale,
                collation_name,
                is_nullable,
                is_identity,
                is_computed,
                is_sparse,
                default_value,
                computed_definition
            FROM @ci;

            ------------------------------------------------------------------
            -- 7. Dependency gate
            ------------------------------------------------------------------
            DECLARE @deps TABLE (dependency nvarchar(1000), type nvarchar(64));
            INSERT @deps
            SELECT dependency, type
            FROM mold.column_dependencies(@full_column);

            DECLARE @blocker nvarchar(1000), @blocker_type nvarchar(64);
            SELECT TOP (1)
                   @blocker      = dependency,
                   @blocker_type = type
            FROM @deps
            WHERE type IN (N'index', N'foreign key', N'computed column', N'view', N'module')
            ORDER BY
                CASE type
                    WHEN N'index'           THEN 1
                    WHEN N'foreign key'     THEN 2
                    WHEN N'computed column' THEN 3
                    WHEN N'view'            THEN 4
                    WHEN N'module'          THEN 5
                    ELSE 99
                END;

            IF @blocker IS NOT NULL
            BEGIN
                DECLARE @dep_msg nvarchar(4000) =
                    N'create_column: cannot alter column because it is referenced by '
                    + CASE @blocker_type
                          WHEN N'index'           THEN N'index '
                          WHEN N'foreign key'     THEN N'foreign key '
                          WHEN N'computed column' THEN N'computed column '
                          WHEN N'view'            THEN N'view '
                          WHEN N'module'          THEN N'module '
                          ELSE N'dependency '
                      END
                    + @blocker
                    + N'. Drop or alter the dependent object first, or change the column manually.';
                ;THROW 50010, @dep_msg, 1;
            END

            ------------------------------------------------------------------
            -- 8. Identity and computed must match, not change
            ------------------------------------------------------------------
            IF (SELECT is_identity FROM @cur) = 1 AND @identity = 0
            BEGIN
                ;THROW 50011, N'create_column: existing column is IDENTITY; cannot convert.', 1;
            END
            IF (SELECT is_identity FROM @cur) = 0 AND @identity = 1
            BEGIN
                ;THROW 50012, N'create_column: existing column is not IDENTITY; cannot convert.', 1;
            END

            IF (SELECT is_computed FROM @cur) = 1 AND @computed = 0
            BEGIN
                ;THROW 50013, N'create_column: existing column is computed; cannot convert to a regular column.', 1;
            END
            IF (SELECT is_computed FROM @cur) = 0 AND @computed = 1
            BEGIN
                ;THROW 50014, N'create_column: existing column is not computed; cannot convert to computed.', 1;
            END

            IF @computed = 1
            BEGIN
                DECLARE @cur_expr nvarchar(max) = (SELECT computed_definition FROM @cur);
                IF mold._normalize_default(@cur_expr) <> mold._normalize_default(@expression)
                BEGIN
                    ;THROW 50015, N'create_column: computed expression differs from existing column.', 1;
                END
            END

            ------------------------------------------------------------------
            -- 9. Build the ALTER statements needed
            ------------------------------------------------------------------
            DECLARE @alter_type       bit = 0,
                    @alter_nullable   bit = 0,
                    @alter_sparse     bit = 0,
                    @alter_default    bit = 0,
                    @new_type         nvarchar(4000),
                    @new_collation    sysname;

            -- 9a. Type change
            IF @computed = 0
            BEGIN
                DECLARE @from_type      nvarchar(128) = (SELECT type_name       FROM @cur),
                        @from_length    int           = (SELECT max_length      FROM @cur),
                        @from_precision int           = (SELECT [precision]     FROM @cur),
                        @from_scale     int           = (SELECT scale           FROM @cur),
                        @cur_collation  sysname       = (SELECT collation_name  FROM @cur),
                        @to_type        nvarchar(128) = (SELECT type_name       FROM @t),
                        @to_length      int           = (SELECT byte_length     FROM @t),
                        @to_precision   int           = (SELECT precision       FROM @t),
                        @to_scale       int           = (SELECT scale           FROM @t),
                        @spec_collation sysname       = (SELECT collation_name  FROM @t);

                IF @from_type <> @to_type
                   OR @from_length <> @to_length
                   OR ISNULL(@from_precision, -1) <> ISNULL(@to_precision, -1)
                   OR ISNULL(@from_scale, -1)     <> ISNULL(@to_scale, -1)
                BEGIN
                    DECLARE @cls nvarchar(20),
                            @needs_data_check bit,
                            @needs_collation_check bit,
                            @reason nvarchar(4000);

                    SELECT
                        @cls = [class],
                        @needs_data_check = requires_data_check,
                        @needs_collation_check = requires_collation_check,
                        @reason = reason
                    FROM mold.column_type_change(
                        @from_type, @from_length, @from_precision, @from_scale,
                        @to_type,   @to_length,   @to_precision,   @to_scale
                    );

                    IF @cls = N'forbidden'
                    BEGIN
                        DECLARE @msg_forbid nvarchar(2048) = N'create_column: ' + @reason;
                        ;THROW 50016, @msg_forbid, 1;
                    END

                    IF @needs_data_check = 1
                    BEGIN
                        DECLARE @bad int;

                        DECLARE @chk nvarchar(max) =
                            N'SELECT @b = COUNT(*) FROM ' + @full_table
                            + N' WHERE ' + QUOTENAME(@name) + N' IS NOT NULL AND ('
                            + N'TRY_CAST(' + QUOTENAME(@name) + N' AS '
                            + (SELECT normalized_type FROM @t) + N') IS NULL';

                        -- Detect silent truncation when narrowing varchar or nvarchar.
                        -- DATALENGTH measures bytes, which matches SQL Server's length
                        -- semantics for these types.
                        IF @from_type = @to_type
                        AND @from_type IN (N'varchar', N'nvarchar')
                        AND @to_length >= 0
                        BEGIN
                            SET @chk +=
                                N' OR DATALENGTH(' + QUOTENAME(@name) + N') > @target_bytes';
                        END

                        SET @chk += N');';

                        EXEC sp_executesql
                            @chk,
                            N'@b int OUTPUT, @target_bytes int',
                            @b = @bad OUTPUT,
                            @target_bytes = @to_length;

                        IF @bad > 0
                        BEGIN
                            DECLARE @msg_data nvarchar(2048) =
                                N'create_column: ' + @reason
                                + N' (' + CAST(@bad AS nvarchar(20)) + N' row(s) would not fit).';

                            ;THROW 50017, @msg_data, 1;
                        END
                    END

                    IF @needs_collation_check = 1
                    BEGIN
                        IF @spec_collation IS NULL
                        BEGIN
                            ;THROW 50018, N'create_column: Unicode-to-non-Unicode change requires an explicit COLLATE clause in @spec.type.', 1;
                        END
                        IF @spec_collation = @cur_collation
                        BEGIN
                            ;THROW 50019, N'create_column: specified collation matches the current one; the encoding change has no effect.', 1;
                        END

                        SET @new_collation = @spec_collation;
                    END

                    SET @alter_type = 1;
                    SET @new_type   = (SELECT normalized_type FROM @t)
                                    + CASE WHEN @needs_collation_check = 1
                                                THEN N' COLLATE ' + @new_collation
                                                ELSE N'' END;
                END
            END

            -- 9b. Nullable
            IF (SELECT is_nullable FROM @cur) <> @nullable
            BEGIN
                IF (SELECT is_nullable FROM @cur) = 1 AND @nullable = 0
                BEGIN
                    DECLARE @has_nulls bit = 0;
                    DECLARE @sql_chk nvarchar(max) =
                        N'SELECT @h = CASE WHEN EXISTS (SELECT 1 FROM ' + @full_table
                        + N' WHERE ' + QUOTENAME(@name) + N' IS NULL) THEN 1 ELSE 0 END;';
                    EXEC sp_executesql @sql_chk, N'@h bit OUTPUT', @h = @has_nulls OUTPUT;

                    IF @has_nulls = 1
                    BEGIN
                        ;THROW 50017, N'create_column: cannot set NOT NULL; column contains NULLs.', 1;
                    END
                END
                SET @alter_nullable = 1;
            END

            -- 9c. Sparse
            IF (SELECT is_sparse FROM @cur) <> @sparse
                SET @alter_sparse = 1;

            -- 9d. Default: delegate to create_default, only when @default is supplied
            IF @default IS NOT NULL
               AND mold.default_exists(@full_column, @default) = 0
                SET @alter_default = 1;

            ------------------------------------------------------------------
            -- 10. No change?
            ------------------------------------------------------------------
            IF @alter_type = 0 AND @alter_nullable = 0 AND @alter_sparse = 0 AND @alter_default = 0
            BEGIN
                IF @started_transaction = 1
                    COMMIT TRANSACTION;

                SELECT status = N'NO CHANGE', detail = N'column already matches spec';
                RETURN;
            END

            ------------------------------------------------------------------
            -- 11. Apply column-level DDL
            ------------------------------------------------------------------
            DECLARE @ddl2 nvarchar(max) = N'';

            IF @alter_type = 1
                SET @ddl2 += N'ALTER TABLE ' + @full_table
                          + N' ALTER COLUMN ' + QUOTENAME(@name) + N' ' + @new_type
                          + CASE
                                WHEN @alter_nullable = 1
                                    THEN CASE WHEN @nullable = 1 THEN N' NULL' ELSE N' NOT NULL' END
                                ELSE CASE WHEN (SELECT is_nullable FROM @cur) = 1 THEN N' NULL' ELSE N' NOT NULL' END
                            END
                          + N'; ';

            IF @alter_nullable = 1 AND @alter_type = 0
                SET @ddl2 += N'ALTER TABLE ' + @full_table
                          + N' ALTER COLUMN ' + QUOTENAME(@name) + N' ' + (SELECT normalized_type FROM @t)
                          + CASE WHEN @nullable = 1 THEN N' NULL' ELSE N' NOT NULL' END
                          + N'; ';

            IF @alter_sparse = 1
                SET @ddl2 += N'ALTER TABLE ' + @full_table
                        + N' ALTER COLUMN ' + QUOTENAME(@name)
                        + CASE
                                WHEN @sparse = 1 THEN N' ADD SPARSE'
                                ELSE N' DROP SPARSE'
                            END
                        + N'; ';

            IF @dry_run = 1
            BEGIN

                IF @alter_default = 1
                BEGIN
                    DECLARE @dry_default nvarchar(max) =
                        N'EXEC ' + QUOTENAME(N'mold') + N'.create_default @column = '
                        + QUOTENAME(@full_column, '''') + N', @value = '
                        + QUOTENAME(@default, '''')
                        + CASE WHEN @default_name IS NOT NULL
                                    THEN N', @name = ' + QUOTENAME(@default_name, '''')
                                    ELSE N'' END + N';';
                END

                IF @started_transaction = 1
                    COMMIT TRANSACTION;

                SELECT status = N'DRY RUN', detail = @ddl2
                       + CASE WHEN @alter_default = 1
                                   THEN N' -- plus create_default for ' + @full_column
                                   ELSE N'' END;
                RETURN;
            END

            IF @ddl2 <> N''
                EXEC sp_executesql @ddl2;

            ------------------------------------------------------------------
            -- 12. Apply default via helper (same transaction, same lock)
            ------------------------------------------------------------------
            IF @alter_default = 1
                EXEC mold.create_default
                     @column = @full_column,
                     @value  = @default,
                     @name   = @default_name;

            IF @started_transaction = 1
                COMMIT TRANSACTION;

            DECLARE @msg_alt nvarchar(4000) = N'create_column: ' + @full_column + N' -> ALTERED';

            SELECT status = N'ALTERED', detail = @ddl2
                   + CASE WHEN @alter_default = 1
                               THEN N' -- default synced via create_default'
                               ELSE N'' END;
        END TRY
        BEGIN CATCH
            IF @started_transaction = 1
            BEGIN
                -- This procedure owns the transaction, so it can roll it
                -- back completely (including releasing its applock).
                IF XACT_STATE() <> 0
                    ROLLBACK TRANSACTION;
            END
            ELSE IF @savepoint_created = 1 AND XACT_STATE() = 1
            BEGIN
                -- The caller owns the transaction. Undo only this
                -- procedure's work; never roll back the caller's transaction.
                ROLLBACK TRANSACTION create_column_savepoint;
            END
            -- If XACT_STATE() = -1 in a caller-owned transaction, SQL Server
            -- does not permit rollback to a savepoint. Leave the full rollback
            -- decision to the caller.
            ;THROW;
        END CATCH
    END TRY
    BEGIN CATCH
        ;THROW;
    END CATCH
END
GO

go
